=<!DOCTYPE html>
<html lang="ar" dir="rtl">
<head>
  <meta charset="UTF-8">
  <title>المساعد الذكي للمعلم</title>
  <link href="[https://fonts.googleapis.com/css2?family=Cairo:wght@400;600;700&display=swap](https://fonts.googleapis.com/css2?family=Cairo:wght@400;600;700&display=swap)" rel="stylesheet">
  <style>
    body {
      font-family: 'Cairo', sans-serif;
      background-color: #f4f6f9;
      color: #333;
      padding: 30px;
      margin: 0;
    }
    .container {
      max-width: 850px;
      margin: auto;
      background: #ffffff;
      padding: 35px;
      border-radius: 14px;
      box-shadow: 0 8px 25px rgba(0,0,0,0.06);
    }
    .header {
      text-align: center;
      border-bottom: 2px solid #eef2f6;
      padding-bottom: 20px;
      margin-bottom: 30px;
    }
    .header h1 { color: #1e3a8a; margin-bottom: 8px; }
    .card {
      background: #f8fafc;
      border-right: 5px solid #3b82f6;
      border-radius: 8px;
      padding: 20px;
      margin-bottom: 25px;
    }
    .card h2 { color: #1e40af; margin-top: 0; }
    ul { line-height: 1.8; }
    .btn-print {
      display: block;
      width: fit-content;
      margin: 25px auto 0;
      padding: 12px 28px;
      background: #2563eb;
      color: white;
      text-decoration: none;
      border-radius: 8px;
      font-weight: 600;
      cursor: pointer;
      border: none;
    }
    .btn-print:hover { background: #1d4ed8; }
    @media print { .btn-print { display: none; } }
  </style>
</head>
<body>
  <div class="container">
    <div class="header">
      <h1>مساعد المعلم الذكي 📚</h1>
      <p>خطة الدرس وبنك الأسئلة التفاعلي</p>
    </div>

    {{ $json.text }}

    <button class="btn-print" onclick="window.print()">🖨️ طباعة أو حفظ كـ PDF</button>
  </div>
</body>
</html>
